 "content": "def transform(grid):
    # The two 5s which touch form the special domino; color it 1.
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    domino = None
    for r, c in cells:
        for dr, dc in ((0, 1), (1, 0)):
            if (r + dr, c + dc) in cells:
                domino = {(r, c), (r + dr, c + dc)}
                break
        if domino is not None:
            break
    out = [[0] * w for _ in range(h)]
    # Preserve separator lines; otherwise fill room background with 3 and
    # place 1s on the adjacent 5-pair cells.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 3
            elif domino and (r, c) in domino:
                out[r][c] = 1
            else:
                out[r][c] = 3
    # Compress the whole field to its 3x3 compartment symbols.
    row_walls = [r for r in range(h) if all(x == 3 for x in grid[r])]
    col_walls = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    def spans(n, walls):
        parts, start = [], 0
        for x in walls:
            parts.append((start, x))
            start = x + 1
        parts.append((start, n))
        return parts
    rows, cols = spans(h, row_walls), spans(w, col_walls)
    result = []
    for r0, r1 in rows:
        line = []
        for c0, c1 in cols:
            line.append(1 if domino and any((r,c) in domino for r in range(r0,r1) for c in range(c0,c1)) else 3)
        result.append(line)
    return result

if __name__ == '__main__':
